mapper.select:


    del_flag = '0'
     AND resource_code LIKE CONCAT('%', #{resource_code}, '%')
     AND resource_name LIKE CONCAT('%', #{resource_name}, '%')
     AND resource_type = #{resource_type}
     AND status = #{status}
     AND workshop_name LIKE CONCAT('%', #{workshop_name}, '%')
     AND date(create_time) >= #{params.beginTime}
     AND date(create_time) <= #{params.endTime}

ORDER BY resource_id DESC
